/**
 * The rand7() API is already defined in the parent class SolBase.
 * var rand7 = function() {}
 * @return {number} a random integer in the range 1 to 7
 */
var rand10 = function() {
    while (true) {
        const row = rand7();
        const col = rand7();
        const idx = (row - 1) * 7 + col;
        if (idx <= 40) {
            return 1 + (idx - 1) % 10;
        }
    }
};
